Definition ipf_WX (lo : Z) (sp : word) (P IN E ff fp : Z) : list (Z * Z) :=
  ipf_W lo sp P IN E ++ [(as_FSB H, as_FSB H + AFS_FLAGS); (fp, fp + 1); (ff, ff + 8192); (sh ff, sh ff + 1024)]%Z.

