Definition ipf_lay (sp : word) (spa : Z) (gsz : nat) : Prop :=
  spa + 216 + Z.of_nat gsz = bv_unsigned sp + -104 /\ bv_unsigned sp + -336 <= spa /\ spa mod 32 = 0.

(* [comment removed for export] *)
Definition ipf_s1f (j0 : list byte) (P E IN ff last : Z) (j128 : list byte) : list cell :=
  [CB 24 j0; C8 (wz (Z.land (P + 72) 7 + 3)); C8 (wz (Z.land E 7 + 3)); C8 (wz (sh7 ff + 4)); C8 (wz ff); C8 (wz ff);
   C8 (wz (sh7 P)); C8 (wz (sh7 (P + 72))); C8 (wz (P + 72)); C8 (wz AG_FIELD_TABLE); C8 (wz AG_FIELD_TABLE_GUARD);
   C8 (wz (ff + 32)); C8 (wz (sh7 IN)); C8 (wz last); CB 16 j128; C8 (wz ff)].

