(* [comment removed for export] *)
Definition ipf_ret_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (LF : list fframe) (P IN E lo shi : Z) (c : pcore) (pad7 pad2 : list byte) (p0 : Z) (bs : list byte) (qlo : Z) (m : mem)
    : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' (q : Z) (E' : ecv) (c' : pcore) (g' : bool) (XS : list (Z * Z)),
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom asegs)
    /\ Forall (fs_scratch H LF) XS
    /\ munch (ipf_W lo sp P IN E ++ (as_FSB H, as_FSB H + AFS_FLAGS) :: XS) m m' /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ stk asegs m' lo (bv_unsigned sp)
    /\ rw_cells asegs m' P (ParserCoreCells c' pad7 pad2) /\ dof_core c c'
    /\ rw_cells asegs m' IN [C8 (wz q)] /\ p0 <= q <= p0 + Z.of_nat (length bs) /\ qlo <= q
    /\ rw_cells asegs m' E (ErrCodeCells E') /\ (E' = EC_clear \/ http_fail E') /\ (E' = EC_clear -> p0 + 2 <= q)
    /\ bytes_at asegs m' p0 bs /\ APfTab m' /\ (AFieldTabZero m' \/ FT m') /\ FTInit m'
    /\ AHttpCat m' g' /\ AXStatics2 m'
    /\ as_RFS H LF m' /\ ACONST m' /\ stack0 m' lo shi.

(* [comment removed for export] *)
Definition ipf_ctx (LF : list fframe) (m m1 : mem) (sp : word) (spa : Z) (gsz : nat) (gj : list byte)
    (rav s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v : word)
    (P IN E p0 : Z) (bs : list byte) (c1 : pcore) (pad7 pad2 : list byte) (q : Z) (ecs : list cell) (g : bool)
    (lo shi ff fp last : Z) (h0 h1 h2 h3 : word) (shb : list byte) (j0 j128 jr jh : list byte) (XS : list (Z * Z)) : Prop :=
  rw_cells asegs m1 (spa + 216) [CB gsz gj]
  /\ rw_cells asegs m1 (bv_unsigned sp + -104) (dof_sav s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v rav)
  /\ rw_cells asegs m1 spa (ipf_s1f j0 P E IN ff last j128)
  /\ rw_cells asegs m1 ff [C8 h0; C8 h1; C8 h2; C8 h3]
  /\ rw_cells asegs m1 (ff + 4136) [CB 4048 jr]
  /\ rw_cells asegs m1 (ff + 8184) [C8 (wz fp)]
  /\ rw_cells asegs m1 (Z.shiftr ff 3 + 2147450880) [CB 552 shb]
  /\ rw_cells asegs m1 (Z.shiftr ff 3 + 2147450880 + 552) [CB 472 jh]
  /\ rw_cells asegs m1 fp [C1 (b8 1)]
  /\ rw_cells asegs m1 P (ParserCoreCells c1 pad7 pad2)
  /\ rw_cells asegs m1 IN [C8 (wz q)]
  /\ rw_cells asegs m1 E ecs
  /\ bytes_at asegs m1 p0 bs /\ APfTab m1 /\ (AFieldTabZero m1 \/ FT m1) /\ FTInit m1
  /\ AHttpCat m1 g
  /\ stk asegs m1 lo spa
  /\ munch (ipf_WX lo sp P IN E ff fp ++ XS) m m1 /\ Forall (fs_scratch H ((7, ff, fp) :: LF)) XS /\ wmono asegs m m1 /\ mem_inv asegs m1
  /\ ipf_side H LF m m1 lo shi ff fp P E p0 (Z.of_nat (length bs))
  /\ bv_unsigned rav mod 2 = 0.

(* [comment removed for export] *)
Definition ipf_bpure (sp : word) (spa : Z) (gsz : nat) (P IN E lo shi : Z) (c : pcore) (p0 last : Z) (bs : list byte) : Prop :=
  ipf_pure sp P IN E lo shi c p0 bs /\ ipf_lay sp spa gsz /\ last = p0 + Z.of_nat (length bs)
  /\ aapp P 256 /\ aapp E 24 /\ aapp p0 (Z.of_nat (length bs)).
End DEFS.

